import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { compareDays, compareMetric, versionOn, type CatalogEntry, type Evolution } from "../lib/evolution";

// Generated by the engine (python -m tools.evaluation.evolution_parity): spec 076 parity.
const parity = JSON.parse(readFileSync(new URL("./fixtures/evolution-parity.json", import.meta.url), "utf-8")) as {
  timelineVersion: string; catalog: Record<string, CatalogEntry>;
  cases: Array<{ metric: string; before: Record<string, unknown>; after: Record<string, unknown>; direction: string }>;
};

test("day X against day Y states exactly what the engine states (spec 076 parity)", () => {
  for (const c of parity.cases) {
    const row = compareMetric(c.metric, parity.catalog[c.metric], c.before, c.after, parity.timelineVersion);
    assert.equal(row.direction, c.direction, `${c.metric} ${JSON.stringify(c.before)} -> ${JSON.stringify(c.after)}`);
  }
});

test("collapsed versions cover every recorded day and an unmeasured day is never zero", () => {
  const evolution: Evolution = {
    timelineVersion: "timeline-v1", days: ["2026-10-13", "2026-10-14", "2026-10-15"],
    versions: [{ from: "2026-10-13", to: "2026-10-14", metrics: { "demand.open_public_calls": 3 } },
      { from: "2026-10-15", to: "2026-10-15", metrics: { "demand.open_public_calls": 9, "reputation.press_mentions": 2 } }],
    catalog: parity.catalog,
  };
  assert.equal(versionOn(evolution, "2026-10-14")?.metrics["demand.open_public_calls"], 3);
  const rows = compareDays(evolution, "2026-10-13", "2026-10-15", { family: null, channel: null });
  assert.equal(rows.find(r => r.key === "demand.open_public_calls")?.direction, "UP");
  assert.equal(rows.find(r => r.key === "reputation.press_mentions")?.direction, "NOT_MEASURED");
  const demandOnly = compareDays(evolution, "2026-10-13", "2026-10-15", { family: "demand", channel: null });
  assert.deepEqual(demandOnly.map(r => r.key), ["demand.open_public_calls"]);
});
